[standards/application/event-driven/STD-APP-EVT-001-dotnet-kafka-consumer.md#consumer-configuration-structure]

### Consumer Configuration Structure

**Required Configuration Classes**

```csharp
using Confluent.Kafka;
using System.Collections.Generic;

/// <summary>
/// Configuration for Kafka consumer connecting to AWS MSK with IAM authentication
/// </summary>
public class KafkaConsumerConfiguration
{
    /// <summary>
    /// AWS MSK broker endpoints (comma-separated)
    /// Example: "b-1.msk-cluster.kafka.us-east-1.amazonaws.com:9098,b-2.msk-cluster.kafka.us-east-1.amazonaws.com:9098"
    /// </summary>
    public string BootstrapServers { get; set; } = string.Empty;

    /// <summary>
    /// Consumer group ID for coordinated consumption
    /// Must be unique per application/microservice
    /// </summary>
    public string GroupId { get; set; } = string.Empty;

    /// <summary>
    /// Kafka topic name to consume from
    /// </summary>
    public string Topic { get; set; } = string.Empty;

    /// <summary>
    /// AWS region where MSK cluster is deployed
    /// </summary>
    public string AwsRegion { get; set; } = "us-east-1";

    /// <summary>
    /// Session timeout in milliseconds (default: 45000ms = 45 seconds)
    /// Consumer is removed from group if no heartbeat within this time
    /// </summary>
    public int SessionTimeoutMs { get; set; } = 45000;

    /// <summary>
    /// Heartbeat interval in milliseconds (default: 3000ms = 3 seconds)
    /// Must be lower than SessionTimeoutMs
    /// </summary>
    public int HeartbeatIntervalMs { get; set; } = 3000;

    /// <summary>
    /// Maximum time between polls in milliseconds (default: 300000ms = 5 minutes)
    /// Consumer is removed if exceeds this interval
    /// </summary>
    public int MaxPollIntervalMs { get; set; } = 300000;

    /// <summary>
    /// What to do when no offset exists: Earliest or Latest
    /// </summary>
    public AutoOffsetReset AutoOffsetReset { get; set; } = AutoOffsetReset.Earliest;

    /// <summary>
    /// Maximum number of messages to fetch per partition (default: 500)
    /// </summary>
    public int MaxPartitionFetchBytes { get; set; } = 1048576; // 1MB

    /// <summary>
    /// Enable automatic offset commits (MUST be false per standard)
    /// </summary>
    public bool EnableAutoCommit { get; set; } = false;

    /// <summary>
    /// Enable automatic offset storage (MUST be false per standard)
    /// </summary>
    public bool EnableAutoOffsetStore { get; set; } = false;

    /// <summary>
    /// Consumer configuration dictionary for Confluent.Kafka
    /// </summary>
    public ConsumerConfig ToConsumerConfig()
    {
        return new ConsumerConfig
        {
            BootstrapServers = BootstrapServers,
            GroupId = GroupId,
            SecurityProtocol = SecurityProtocol.SaslSsl,
            SaslMechanism = SaslMechanism.OAuthBearer,
            SaslOauthbearerMethod = SaslOauthbearerMethod.Oidc,
            SaslOauthbearerTokenEndpointUrl = $"https://sts.{AwsRegion}.amazonaws.com",
            SaslOauthbearerScope = "kafka-cluster:ReadData",
            SessionTimeoutMs = SessionTimeoutMs,
            HeartbeatIntervalMs = HeartbeatIntervalMs,
            MaxPollIntervalMs = MaxPollIntervalMs,
            AutoOffsetReset = AutoOffsetReset,
            EnableAutoCommit = EnableAutoCommit,
            EnableAutoOffsetStore = EnableAutoOffsetStore,
            MaxPartitionFetchBytes = MaxPartitionFetchBytes,
            // Statistics interval for monitoring (60 seconds)
            StatisticsIntervalMs = 60000,
            // Enable idempotence
            EnableIdempotence = true,
            // Logging
            Debug = "broker,security"
        };
    }
}
```

