#### Step 2.1: Implement Message Consumption Loop

```csharp
private async Task ConsumeMessages(CancellationToken cancellationToken)
{
    try
    {
        var consumeResult = _consumer.Consume(TimeSpan.FromSeconds(1));

        if (consumeResult == null)
            return;

        _logger.LogInformation(
            "Received message: Topic={Topic}, Partition={Partition}, Offset={Offset}, Key={Key}",
            consumeResult.Topic,
            consumeResult.Partition.Value,
            consumeResult.Offset.Value,
            consumeResult.Message.Key);

        // Process message with retry policy
        await ProcessMessageWithRetry(consumeResult, cancellationToken);

        // Commit offset only after successful processing
        _consumer.Commit(consumeResult);

        _logger.LogDebug("Offset committed: {Offset}", consumeResult.Offset.Value);
    }
    catch (ConsumeException ex)
    {
        _logger.LogError(ex, "Error consuming message: {Error}", ex.Error.Reason);
    }
}
```

