#### Step 2.2: Implement Retry Logic with Polly

```csharp
using Polly;
using Polly.Retry;

private readonly AsyncRetryPolicy _retryPolicy = Policy
    .Handle<Exception>(ex => !(ex is InvalidOperationException)) // Don't retry validation errors
    .WaitAndRetryAsync(
        retryCount: 3,
        sleepDurationProvider: retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)),
        onRetry: (exception, timeSpan, retryCount, context) =>
        {
            var logger = context.GetLogger();
            logger.LogWarning(
                exception,
                "Retry {RetryCount} after {Delay}s due to: {Error}",
                retryCount,
                timeSpan.TotalSeconds,
                exception.Message);
        });

private async Task ProcessMessageWithRetry(
    ConsumeResult<string, string> result,
    CancellationToken cancellationToken)
{
    var context = new Context
    {
        ["MessageKey"] = result.Message.Key,
        ["Partition"] = result.Partition.Value,
        ["Offset"] = result.Offset.Value
    };

    try
    {
        await _retryPolicy.ExecuteAsync(
            async (ctx, ct) => await ProcessMessage(result, ct),
            context,
            cancellationToken);
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "Failed to process message after retries");
        await SendToDeadLetterQueue(result, ex);
    }
}
```

