#### Step 3.2: Add Distributed Tracing

```csharp
using System.Diagnostics;

private static readonly ActivitySource ActivitySource = new("Kafka.Consumer");

private async Task ProcessMessageWithTracing(
    ConsumeResult<string, string> result,
    CancellationToken cancellationToken)
{
    using var activity = ActivitySource.StartActivity(
        "ProcessKafkaMessage",
        ActivityKind.Consumer);

    activity?.SetTag("messaging.system", "kafka");
    activity?.SetTag("messaging.destination", result.Topic);
    activity?.SetTag("messaging.kafka.partition", result.Partition.Value);
    activity?.SetTag("messaging.kafka.offset", result.Offset.Value);
    activity?.SetTag("messaging.kafka.message_key", result.Message.Key);

    try
    {
        await ProcessMessageWithRetry(result, cancellationToken);
        activity?.SetStatus(ActivityStatusCode.Ok);
    }
    catch (Exception ex)
    {
        activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
        activity?.RecordException(ex);
        throw;
    }
}
```

