```csharp
using Confluent.Kafka;
using MediatR;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Polly;
using Polly.Retry;
using System.Diagnostics;
using System.Diagnostics.Metrics;
using System.Text;

public class KafkaConsumerService : BackgroundService
{
    private readonly ILogger<KafkaConsumerService> _logger;
    private readonly IMediator _mediator;
    private readonly KafkaConsumerConfiguration _config;
    private IConsumer<string, string>? _consumer;
    private IProducer<string, string>? _dlqProducer;

    private static readonly ActivitySource ActivitySource = new("Kafka.Consumer");
    private static readonly Meter Meter = new("Kafka.Consumer");
    private static readonly Counter<long> MessagesProcessed =
        Meter.CreateCounter<long>("kafka.consumer.messages.processed");
    private static readonly Counter<long> MessagesFailed =
        Meter.CreateCounter<long>("kafka.consumer.messages.failed");
    private static readonly Histogram<double> ProcessingDuration =
        Meter.CreateHistogram<double>("kafka.consumer.processing.duration", "ms");

    private readonly AsyncRetryPolicy _retryPolicy;
    private readonly HashSet<string> _processedIds = new(); // In-memory deduplication

    public KafkaConsumerService(
        ILogger<KafkaConsumerService> logger,
        IMediator mediator,
        IOptions<KafkaConsumerConfiguration> config)
    {
        _logger = logger;
        _mediator = mediator;
        _config = config.Value;

        _retryPolicy = Policy
            .Handle<Exception>(ex => !(ex is InvalidOperationException))
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
                onRetry: (ex, delay, attempt, ctx) =>
                {
                    _logger.LogWarning(ex,
                        "Retry {Attempt} after {Delay}s: {Error}",
                        attempt, delay.TotalSeconds, ex.Message);
                });
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var consumerConfig = _config.ToConsumerConfig();

        _consumer = new ConsumerBuilder<string, string>(consumerConfig)
            .SetErrorHandler((_, e) =>
                _logger.LogError("Kafka error: Code={Code}, Reason={Reason}",
                    e.Code, e.Reason))
            .SetStatisticsHandler((_, json) =>
                _logger.LogDebug("Kafka statistics: {Stats}", json))
            .SetLogHandler((_, log) =>
                _logger.Log(
                    log.Level switch
                    {
                        SyslogLevel.Emergency => LogLevel.Critical,
                        SyslogLevel.Alert => LogLevel.Critical,
                        SyslogLevel.Critical => LogLevel.Critical,
                        SyslogLevel.Error => LogLevel.Error,
                        SyslogLevel.Warning => LogLevel.Warning,
                        SyslogLevel.Notice => LogLevel.Information,
                        SyslogLevel.Info => LogLevel.Information,
                        _ => LogLevel.Debug
                    },
                    "Kafka: {Message}", log.Message))
            .Build();

        // Create DLQ producer
        _dlqProducer = new ProducerBuilder<string, string>(
            new ProducerConfig { BootstrapServers = _config.BootstrapServers })
            .Build();

        _consumer.Subscribe(_config.Topic);

        _logger.LogInformation(
            "Kafka consumer started: GroupId={GroupId}, Topic={Topic}, BootstrapServers={Servers}",
            _config.GroupId, _config.Topic, _config.BootstrapServers);

        try
        {
            while (!stoppingToken.IsCancellationRequested)
            {
                await ConsumeMessage(stoppingToken);
            }
        }
        catch (OperationCanceledException)
        {
            _logger.LogInformation("Consumer operation cancelled - shutting down gracefully");
        }
        catch (Exception ex)
        {
            _logger.LogCritical(ex, "Fatal error in consumer loop");
            throw;
        }
        finally
        {
            // Graceful shutdown
            _consumer.Close();
            _consumer.Dispose();
            _dlqProducer?.Dispose();
            _logger.LogInformation("Kafka consumer stopped");
        }
    }

    private async Task ConsumeMessage(CancellationToken cancellationToken)
    {
        try
        {
            var result = _consumer.Consume(TimeSpan.FromMilliseconds(100));
            if (result == null) return;

            var sw = Stopwatch.StartNew();

            using var activity = ActivitySource.StartActivity("ProcessKafkaMessage", ActivityKind.Consumer);
            activity?.SetTag("messaging.system", "kafka");
            activity?.SetTag("messaging.destination", result.Topic);
            activity?.SetTag("messaging.kafka.partition", result.Partition.Value);
            activity?.SetTag("messaging.kafka.offset", result.Offset.Value);
            activity?.SetTag("messaging.kafka.message_key", result.Message.Key);

            _logger.LogInformation(
                "Processing message: Topic={Topic}, Partition={Partition}, Offset={Offset}, Key={Key}",
                result.Topic, result.Partition.Value, result.Offset.Value, result.Message.Key);

            try
            {
                await ProcessMessageWithRetry(result, cancellationToken);

                // Commit offset only after successful processing
                _consumer.Commit(result);

                MessagesProcessed.Add(1,
                    new KeyValuePair<string, object?>("topic", result.Topic));

                activity?.SetStatus(ActivityStatusCode.Ok);

                _logger.LogDebug("Message processed successfully: Offset={Offset}",
                    result.Offset.Value);
            }
            catch (Exception ex)
            {
                MessagesFailed.Add(1,
                    new KeyValuePair<string, object?>("topic", result.Topic));

                activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
                activity?.RecordException(ex);

                _logger.LogError(ex,
                    "Failed to process message after retries: Offset={Offset}",
                    result.Offset.Value);

                await SendToDeadLetterQueue(result, ex);

                // Commit offset even for failed messages to move forward
                _consumer.Commit(result);
            }
            finally
            {
                ProcessingDuration.Record(sw.ElapsedMilliseconds,
                    new KeyValuePair<string, object?>("topic", result.Topic));
            }
        }
        catch (ConsumeException ex)
        {
            _logger.LogError(ex, "Error consuming message: {Error}", ex.Error.Reason);
        }
    }

    private async Task ProcessMessageWithRetry(
        ConsumeResult<string, string> result,
        CancellationToken cancellationToken)
    {
        await _retryPolicy.ExecuteAsync(async () =>
        {
            // Check for duplicate (idempotent processing)
            var messageKey = result.Message.Key;
            if (_processedIds.Contains(messageKey))
            {
                _logger.LogInformation("Skipping duplicate message: Key={Key}", messageKey);
                return;
            }

            // Deserialize and validate (would use Avro schema here)
            var messageEvent = DeserializeMessage(result.Message.Value);

            // Publish to MediatR handlers for processing
            await _mediator.Publish(messageEvent, cancellationToken);

            // Mark as processed
            _processedIds.Add(messageKey);

            // Cleanup old IDs (simple strategy - production would use distributed cache)
            if (_processedIds.Count > 10000)
            {
                _processedIds.Clear();
            }
        });
    }

    private INotification DeserializeMessage(string messageValue)
    {
        // In production, deserialize using Avro schema from AWS Glue Schema Registry
        // For this example, simple JSON deserialization
        return new GenericMessageEvent { Data = messageValue };
    }

    private async Task SendToDeadLetterQueue(
        ConsumeResult<string, string> result,
        Exception exception)
    {
        var dlqTopic = $"{_config.Topic}.dlq";

        var dlqMessage = new Message<string, string>
        {
            Key = result.Message.Key,
            Value = result.Message.Value,
            Headers = new Headers
            {
                { "original-topic", Encoding.UTF8.GetBytes(result.Topic) },
                { "original-partition", BitConverter.GetBytes(result.Partition.Value) },
                { "original-offset", BitConverter.GetBytes(result.Offset.Value) },
                { "error-message", Encoding.UTF8.GetBytes(exception.Message) },
                { "error-type", Encoding.UTF8.GetBytes(exception.GetType().Name) },
                { "timestamp", Encoding.UTF8.GetBytes(DateTimeOffset.UtcNow.ToString("O")) }
            }
        };

        try
        {
            await _dlqProducer!.ProduceAsync(dlqTopic, dlqMessage);
            _logger.LogWarning(
                "Message sent to DLQ: Topic={DlqTopic}, OriginalOffset={Offset}",
                dlqTopic, result.Offset.Value);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to send message to DLQ");
        }
    }
}

